import{_ as a,o as d,c as e,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const b=JSON.parse('{"title":"第 16 章 团队协作：从个人到 AI 团队","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md"}'),n={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md"};function r(o,t,l,i,h,p){return d(),e("div",null,[...t[0]||(t[0]=[s(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 16 章 团队协作：从个人到 AI 团队（易懂版）](../../easy/第16章 团队协作：从个人到 AI 团队（易懂版）.md)</p></div><h1 id="第-16-章-团队协作-从个人到-ai-团队" tabindex="-1">第 16 章 团队协作：从个人到 AI 团队 <a class="header-anchor" href="#第-16-章-团队协作-从个人到-ai-团队" aria-label="Permalink to &quot;第 16 章 团队协作：从个人到 AI 团队&quot;">​</a></h1><blockquote><p>本章目标：掌握团队协作的完整方法论——如何分角色、走流程、避坑、以及 Leader 的管理动作。<strong>AI 团队协作的本质是把复杂度结构化：Leader 的价值不在干活最多，而在拆得最清、验得最严。</strong></p></blockquote><h2 id="_16-1-场景-建团只是开始-协作才是关键" tabindex="-1">16.1 场景：建团只是开始，协作才是关键 <a class="header-anchor" href="#_16-1-场景-建团只是开始-协作才是关键" aria-label="Permalink to &quot;16.1 场景：建团只是开始，协作才是关键&quot;">​</a></h2><p>第 8 章讲了怎么&quot;召唤&quot;团队。这一章讲怎么&quot;用好&quot;团队——因为建团只是开始，<strong>协作才是关键</strong>。</p><p>真实场景：一个产品上线任务，涉及需求梳理、技术方案、开发、测试、文档。一个人（哪怕是我）串行做，又慢又容易顾此失彼；拆给多个角色并行，质量和速度都能上一个台阶。</p><h2 id="_16-2-团队怎么分角色" tabindex="-1">16.2 团队怎么分角色 <a class="header-anchor" href="#_16-2-团队怎么分角色" aria-label="Permalink to &quot;16.2 团队怎么分角色&quot;">​</a></h2><p>分角色的原则：<strong>按任务的自然边界分，不按人数堆。</strong></p><h3 id="_16-2-1-典型角色" tabindex="-1">16.2.1 典型角色 <a class="header-anchor" href="#_16-2-1-典型角色" aria-label="Permalink to &quot;16.2.1 典型角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>职责</th><th>对应任务</th></tr></thead><tbody><tr><td><strong>规划</strong></td><td>拆解、定优先级</td><td>需求梳理、任务分配</td></tr><tr><td><strong>开发</strong></td><td>实现功能</td><td>写代码、改代码</td></tr><tr><td><strong>测试</strong></td><td>验证质量</td><td>写测试、跑测试、报告</td></tr><tr><td><strong>文档</strong></td><td>沉淀交付物</td><td>文档、教程、报告</td></tr><tr><td><strong>评审</strong></td><td>把关</td><td>检查交付物、找问题</td></tr></tbody></table><h3 id="_16-2-2-分角色的三个原则" tabindex="-1">16.2.2 分角色的三个原则 <a class="header-anchor" href="#_16-2-2-分角色的三个原则" aria-label="Permalink to &quot;16.2.2 分角色的三个原则&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 边界清晰：每个任务只有一个唯一负责人（避免两个成员做同一件事）</span></span>
<span class="line"><span>2. 角色互补：开发 + 测试天然互补（写的人不验自己的人）</span></span>
<span class="line"><span>3. 产出明确：每个角色都清楚自己的交付物和验收标准</span></span></code></pre></div><h2 id="_16-3-团队协作的标准流程" tabindex="-1">16.3 团队协作的标准流程 <a class="header-anchor" href="#_16-3-团队协作的标准流程" aria-label="Permalink to &quot;16.3 团队协作的标准流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Leader（我）拆解任务，定义每个子任务的产出标准</span></span>
<span class="line"><span>2. 分派：每个成员拿到明确的任务和验收标准</span></span>
<span class="line"><span>3. 并行执行：成员各自干活，互不干扰</span></span>
<span class="line"><span>4. 中间同步：关键节点向 Leader 汇报</span></span>
<span class="line"><span>5. 交叉验证：测试验开发、评审验全部</span></span>
<span class="line"><span>6. 汇总交付：Leader 整合成最终交付物</span></span>
<span class="line"><span>7. 复盘：哪些任务拆得好、哪些拆得差</span></span></code></pre></div><h3 id="_16-3-1-每一步的产物" tabindex="-1">16.3.1 每一步的产物 <a class="header-anchor" href="#_16-3-1-每一步的产物" aria-label="Permalink to &quot;16.3.1 每一步的产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>产出</th><th>谁看</th></tr></thead><tbody><tr><td>拆解</td><td>任务清单 + 产出标准</td><td>Leader、你</td></tr><tr><td>分派</td><td>每个成员的任务说明</td><td>成员</td></tr><tr><td>执行</td><td>子任务产物</td><td>Leader</td></tr><tr><td>同步</td><td>进度报告</td><td>Leader、你</td></tr><tr><td>验证</td><td>测试报告</td><td>Leader</td></tr><tr><td>交付</td><td>整合后的最终交付物</td><td>你</td></tr></tbody></table><h2 id="_16-4-团队协作的常见坑" tabindex="-1">16.4 团队协作的常见坑 <a class="header-anchor" href="#_16-4-团队协作的常见坑" aria-label="Permalink to &quot;16.4 团队协作的常见坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>症状</th><th>解法</th></tr></thead><tbody><tr><td>任务拆不清</td><td>成员互相等</td><td>子任务边界明确，产出标准写清</td></tr><tr><td>没有中间检查</td><td>最后全错</td><td>关键节点设同步/检查点</td></tr><tr><td>角色重叠</td><td>两成员做同一件事</td><td>明确唯一负责人</td></tr><tr><td>需求漂移</td><td>做到一半改需求</td><td>变更先经过 Leader 重新排期</td></tr></tbody></table><h3 id="_16-4-1-拆不清的根源" tabindex="-1">16.4.1 拆不清的根源 <a class="header-anchor" href="#_16-4-1-拆不清的根源" aria-label="Permalink to &quot;16.4.1 拆不清的根源&quot;">​</a></h3><p><strong>子任务边界模糊 = 依赖关系失控。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>拆不清：开发&quot;做登录功能&quot;、测试&quot;测登录功能&quot;（但开发还没做完，测试就闲着）</span></span>
<span class="line"><span>拆得清：开发&quot;实现登录 API（产出：接口 + 自测通过）&quot;→ 完成后再派测试</span></span></code></pre></div><p><strong>拆任务时明确&quot;输入 → 动作 → 输出 → 验收&quot;，依赖关系就清晰了。</strong></p><h2 id="_16-5-我作为-leader-会怎么管" tabindex="-1">16.5 我作为 Leader 会怎么管 <a class="header-anchor" href="#_16-5-我作为-leader-会怎么管" aria-label="Permalink to &quot;16.5 我作为 Leader 会怎么管&quot;">​</a></h2><h3 id="_16-5-1-管理动作清单" tabindex="-1">16.5.1 管理动作清单 <a class="header-anchor" href="#_16-5-1-管理动作清单" aria-label="Permalink to &quot;16.5.1 管理动作清单&quot;">​</a></h3><ul><li><strong>任务看板</strong>：谁在做什么、谁被谁阻塞、哪些完成了，一目了然；</li><li><strong>阻塞管理</strong>：发现成员被卡住，我来协调或换人；</li><li><strong>验收把关</strong>：每个子任务交付后我检查，不合格打回；</li><li><strong>及时收缩</strong>：任务变小了，关掉冗余成员，不让团队空转。</li></ul><h3 id="_16-5-2-leader-的三种检查节奏" tabindex="-1">16.5.2 Leader 的三种检查节奏 <a class="header-anchor" href="#_16-5-2-leader-的三种检查节奏" aria-label="Permalink to &quot;16.5.2 Leader 的三种检查节奏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>节奏</th><th>时机</th><th>动作</th></tr></thead><tbody><tr><td>任务开始时</td><td>分派后</td><td>确认成员理解任务（对齐一次）</td></tr><tr><td>关键节点</td><td>里程碑</td><td>检查中间产物</td></tr><tr><td>交付前</td><td>最终</td><td>验收把关 + 汇总</td></tr></tbody></table><h2 id="_16-6-单人还是团队-最终决策表" tabindex="-1">16.6 单人还是团队：最终决策表 <a class="header-anchor" href="#_16-6-单人还是团队-最终决策表" aria-label="Permalink to &quot;16.6 单人还是团队：最终决策表&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务很小/探索性质      → 单人</span></span>
<span class="line"><span>任务可拆成多个独立子任务 → 团队</span></span>
<span class="line"><span>任务有多个专业角色要求  → 团队</span></span>
<span class="line"><span>需求不明确，还在探索   → 先单人，想清楚再上团队</span></span>
<span class="line"><span>任务突然缩小           → 收缩回单人，别让团队空转</span></span></code></pre></div><h3 id="_16-6-1-成本意识" tabindex="-1">16.6.1 成本意识 <a class="header-anchor" href="#_16-6-1-成本意识" aria-label="Permalink to &quot;16.6.1 成本意识&quot;">​</a></h3><p><strong>开团队有成本</strong>（协调开销、模型资源）。不要为了&quot;看起来专业&quot;而开团：</p><ul><li>小任务开团队 = 杀鸡用牛刀；</li><li>探索性任务开团队 = 团队做无用功；</li><li>正确姿势：<strong>先单人探索验证，再团队规模化执行。</strong></li></ul><h2 id="_16-7-团队-×-其他章节" tabindex="-1">16.7 团队 × 其他章节 <a class="header-anchor" href="#_16-7-团队-×-其他章节" aria-label="Permalink to &quot;16.7 团队 × 其他章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组合</th><th>用法</th><th>参考</th></tr></thead><tbody><tr><td>团队 + 计划</td><td>大计划拆成子任务分派</td><td>第 7 章</td></tr><tr><td>团队 + Skill</td><td>成员执行时调用专业 Skill</td><td>第 5、17 章</td></tr><tr><td>团队 + 自动化</td><td>团队流程定期自动触发</td><td>第 15 章</td></tr><tr><td>团队 + 记忆</td><td>共享团队上下文与决策</td><td>第 6、20 章</td></tr></tbody></table><h2 id="_16-8-练习" tabindex="-1">16.8 练习 <a class="header-anchor" href="#_16-8-练习" aria-label="Permalink to &quot;16.8 练习&quot;">​</a></h2><ol><li>把一个真实项目按&quot;角色边界&quot;拆成 3～5 个子任务；</li><li>让我按这个拆分建团并分派，观察每个成员的理解是否一致；</li><li>走完一轮&quot;派活 → 执行 → 验收&quot;，复盘拆分质量；</li><li>用 16.4 的坑表自查：这次协作踩了哪个坑？下次怎么避免？</li></ol><hr><blockquote><p>小结：AI 团队协作的本质是<strong>把复杂度结构化</strong>。Leader 的价值不在干活最多，而在拆得最清、验得最严。<strong>角色边界清晰 + 检查节奏固定 + 成本动态可控</strong>，就是团队协作的全部心法。下一篇，进入进阶：把经验变成系统。</p></blockquote>`,38)])])}const u=a(n,[["render",r]]);export{b as __pageData,u as default};
